import os
from moler.config import load_config  # type: ignore
from taf.ul.moler.converter.moler_converter import MolerConverter  # type: ignore
from taf.ul.sc.perf.testline import PerformanceTestLine
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore

from taf.ul.sc.perf.devices.bts.gnb import AirScaleGnb
from taf.ul.sc.perf.devices.bts.enb import AirScaleEnb
from taf.ul.sc.perf.devices.bts.enb import FzpEnb
from taf.ul.sc.enb.airscale import AirScale  # type: ignore
from taf.ul.sc.enb.airscale.fct import Fct  # type: ignore
# from taf.ul.sc.enb.airscale.fsp import Fsp
from taf.ul.sc.enb.fzp import Fzp  # type: ignore
from taf.ul.sc.enb.fzp.fzp_functionality import FzpFunctionality  # type: ignore
from taf.ul.sc.perf.devices.bts.coam import COAM
from taf.ul.sc.perf.devices.bts.ems import Ems
from taf.ul.sc.oam.emssim import Emssim  # type: ignore
from taf.ul.sc.oam.emssim import Workstation as EmsWorkstation  # type: ignore
from taf.ul.sc.syslog import Syslog  # type: ignore

from taf.ul.sc.perf.devices.ue import RTG
from taf.ul.sc.uesim.rtg import Executor as RtgExecutor  # type: ignore
from taf.ul.sc.uesim.rtg import Workstation as RtgWorkstation  # type: ignore
# from taf.ul.sc.uesim.rtg import Controller
from taf.ul.sc.perf.devices.ue import CUS
from taf.ul.sc.uesim.cus.executor import Executor as CusExecutor  # type: ignore
from taf.ul.sc.uesim.cus.workstation import Workstation as CusWorkstation  # type: ignore

from taf.ul.sc.perf.devices.core import EpcSim
from taf.ul.sc.epcsim import Egate  # type: ignore
from taf.ul.sc.epcsim import Workstation as EPCWorkstation  # type: ignore

from taf.ul.sc.perf.util.robot_helpers import get_builtin_value
from taf.ul.sc.perf.util.helpers import get_defined_kwargs


class TestLineGenerator(object):

    __tl = None

    def __init__(self, conf=None, create_at_startup=True):
        self.conf = conf
        self.create_at_startup = create_at_startup
        self.mlc = MolerConverter()
        self.mlc._config = {'DEVICES': {}}

    @property
    def tl(self):
        return type(self).__tl

    def generate_test_line(self):
        self.prepare_moler_configuration()
        load_config(config=self.mlc._config, config_type='dict')

        btss = self.get_btss()
        ue = self.get_ue()
        core = self.get_core()

        type(self).__tl = PerformanceTestLine(
            unix_local=UnixFunctionality(device_name='UnixLocal', autoconnect=self.create_at_startup),
            btss=btss,
            ue=ue,
            core=core,
            owner=self.conf['owner'],
            name=self.conf['name'],
            tl_type=self.conf.get('tl_type', None),
            maintainers=self.conf.get('maintainers', None)
        )

    def generate_default_test_line_configuration(self):
        self.prepare_moler_configuration()
        load_config(config=self.mlc._config, config_type='dict')

    def prepare_moler_configuration(self):

        logger_params = self._get_logger_params()
        self.mlc._config.update(self.mlc._build_logger_configuration(params=logger_params))
        self.mlc.moler_devices.add_default_connection()
        self.mlc.moler_devices.add_local_unix_configuration()
        self.mlc.moler_devices.add_create_at_startup(create_at_startup=False)

        for bts_id, bts_config in enumerate(self.conf['btss']):
            self._add_full_bts_moler_configuration(bts_config, bts_id)

        self._add_ue_moler_configuration()
        self._add_core_moler_configuration()

        self.mlc._config['DEVICES'].update(self.mlc.moler_devices.get_moler_device_config()['DEVICES'])

    def _get_logger_params(self):
        log_dir = os.path.join(get_builtin_value(param_name="OUTPUT DIR"), "moler")
        log_level = get_builtin_value(param_name="LOG LEVEL")

        logger_params = {
            'PATH': log_dir,
            'DEBUG_LEVEL': log_level
        }

        return logger_params

    def _add_ue_moler_configuration(self):
        ue_type = self.conf['ue']['type']
        if ue_type == 'RTG':
            self._add_rtg_moler_configuration()
        if ue_type == 'CUS':
            self._add_cus_moler_configuration()

    def _add_rtg_moler_configuration(self):

        self.mlc.moler_devices.add_rtg_configuration(
            device_name='RTG',
            host=self.conf['ue']['workstation']['host'],
            login=self.conf['ue']['workstation']['login'],
            password=self.conf['ue']['workstation']['password'],
            root_password=self.conf['ue']['workstation']['root_password']
        )

        self.mlc.moler_devices.add_rtg_ws_configuration(
            device_name='RTG_WS',
            host=self.conf['ue']['workstation']['host'],
            login=self.conf['ue']['workstation']['login'],
            password=self.conf['ue']['workstation']['password'],
            root_password=self.conf['ue']['workstation']['root_password']
        )

    def _add_cus_moler_configuration(self):

        self.mlc.moler_devices.add_cus_configuration(
            device_name='CUS',
            host=self.conf['ue']['workstation']['host'],
            login=self.conf['ue']['workstation']['login'],
            password=self.conf['ue']['workstation']['password'],
            root_password=self.conf['ue']['workstation']['root_password']
        )

        self.mlc.moler_devices.add_cus_ws_configuration(
            device_name='CUS_WS',
            host=self.conf['ue']['workstation']['host'],
            login=self.conf['ue']['workstation']['login'],
            password=self.conf['ue']['workstation']['password'],
            root_password=self.conf['ue']['workstation']['root_password']
        )
        self.conf['ue']['workstation']['syslog_path'] = (
            self.conf['ue']['workstation'].get('syslog_path', "/home/cus/cus_syslog_dir")
        )
        self.conf['ue']['workstation']['syslog_mask'] = (
            self.conf['ue']['workstation'].get('syslog_mask', "syslog_ctrl*")
        )
        self._add_syslog_moler_configuration_v2(device_name="{}_SYSLOG".format("CUS"),
                                                syslog_config=self.conf['ue']['workstation'])

    def _add_full_bts_moler_configuration(self, bts_config, bts_id):
        bts_prefix = 'BTS'

        self._add_bts_moler_configuration(device_name="{}{}".format(bts_prefix, bts_id),
                                          bts_type=bts_config['type'],
                                          bts_lmp_ip=bts_config.get('lmp_ip', '192.168.255.129'),
                                          bts_ws_config=bts_config['workstation'])
        if bts_config.get('workstation'):
            self._add_bts_ws_moler_configuration(device_name="{}{}_WS".format(bts_prefix, bts_id),
                                                 ws_config=bts_config['workstation'])
        if bts_config.get('ems'):
            self._add_ems_moler_configuration(device_name="EMSSIM{}".format(bts_id),
                                              ems_config=bts_config['ems'])
            self._add_ems_ws_moler_configuration(device_name="EMSSIM{}_WS".format(bts_id),
                                                 ems_config=bts_config['ems'])
        if bts_config.get('syslog'):
            self._add_syslog_moler_configuration(device_name="{}{}_SYSLOG".format(bts_prefix, bts_id),
                                                 syslog_config=bts_config['workstation'])

    def _add_bts_moler_configuration(self, device_name, bts_type, bts_lmp_ip, bts_ws_config):
        if bts_type in ['AirScaleEnb', 'AirScaleGnb']:
            self.mlc.moler_devices.add_airscale_configuration(
                device_name=device_name,
                fct_host=bts_lmp_ip,
                fsp_host='192.168.253.34',
                login='toor4nsn',
                password='oZPS0POrRieRtu',
                proxy_pc_host=bts_ws_config['host'],
                proxy_pc_login=bts_ws_config['login'],
                proxy_pc_password=bts_ws_config['password']
            )
        elif bts_type in ['FzpEnb']:
            self.mlc.moler_devices.add_enb_configuration(
                device_name=device_name,
                proxy_pc_host=bts_ws_config['host'],
                proxy_pc_login=bts_ws_config['login'],
                proxy_pc_password=bts_ws_config['password'],
                host=bts_lmp_ip,
                login='toor4nsn',
                password='oZPS0POrRieRtu'
            )

    def _add_bts_ws_moler_configuration(self, device_name, ws_config):
        self.mlc.moler_devices.add_enb_ws_configuration(
            device_name=device_name,
            host=ws_config['host'],
            login=ws_config['login'],
            password=ws_config['password']
        )

    def _add_ems_moler_configuration(self, device_name, ems_config):
        proxy_pc_params = self.get_proxy_pc_params(config=ems_config)
        self.mlc.moler_devices.add_enb_emssim_configuration(
            device_name=device_name,
            host=ems_config['host'],
            port=ems_config['port'],
            **proxy_pc_params
        )

    def _add_ems_ws_moler_configuration(self, device_name, ems_config):
        proxy_pc_params = self.get_proxy_pc_params(config=ems_config)
        self.mlc.moler_devices.add_emssim_ws_configuration(
            device_name=device_name,
            host=ems_config['host'],
            login=ems_config['login'],
            password=ems_config['password'],
            ** proxy_pc_params
        )

    def _add_syslog_moler_configuration(self, device_name, syslog_config):
        self.mlc.moler_devices.add_syslog_configuration(
            device_name=device_name,
            host=syslog_config['host'],
            login=syslog_config['login'],
            password=syslog_config['password']
        )

    def _add_syslog_moler_configuration_v2(self,
                                           device_name,
                                           syslog_config):
        self.mlc.moler_devices.add_syslog_configuration_v2(
            device_name=device_name,
            host=syslog_config['host'],
            login=syslog_config['login'],
            password=syslog_config['password'],
            syslog_path=syslog_config.get('syslog_path', '/tmp/btslog2'),
            syslog_mask=syslog_config.get('syslog_mask', 'SYSLOG*'),
        )

    def _add_core_moler_configuration(self):
        if self.conf.get('core', None):
            if self.conf['core']['type'] == 'EPCsim':
                self._add_epcsim_moler_configuration(device_name='EPCSIM', core_config=self.conf['core'])
                self._add_epcsim_ws_moler_configuration(device_name='EPCSIM_WS', core_config=self.conf['core'])

    def _add_epcsim_moler_configuration(self, device_name, core_config):
        proxy_pc_params = self.get_proxy_pc_params(config=core_config['cli'])
        self.mlc.moler_devices.add_epcsim_configuration(
            device_name=device_name,
            host=core_config['workstation']['host'],
            port=core_config['cli']['port'],
            **proxy_pc_params
        )

    def _add_epcsim_ws_moler_configuration(self, device_name, core_config):
        proxy_pc_params = self.get_proxy_pc_params(config=core_config['workstation'])
        self.mlc.moler_devices.add_epcsim_ws_configuration(
            device_name=device_name,
            host=core_config['workstation']['host'],
            login=core_config['workstation']['login'],
            password=core_config['workstation']['password'],
            root_password=core_config['workstation']['root_password'],
            **proxy_pc_params
        )

    def get_ue(self):
        ue = None
        ue_type = self.conf['ue']['type']
        if ue_type == 'RTG':
            ue = RTG(
                executor=RtgExecutor(device_name='RTG', autoconnect=self.create_at_startup),
                workstation=RtgWorkstation(device_name='RTG_WS', autoconnect=self.create_at_startup),
                controllers=None
            )
        if ue_type == 'CUS':
            syslog = Syslog(device_name="CUS_SYSLOG", get_device=True)
            ue = CUS(
                executor=CusExecutor(device_name='CUS', autoconnect=self.create_at_startup),
                workstation=CusWorkstation(device_name='CUS_WS', autoconnect=self.create_at_startup),
                controllers=None,
                syslog=syslog
            )
        return ue

    def get_core(self):
        core = None
        if self.conf.get('core', None):
            if self.conf['core']['type'] == 'EPCsim':
                kwargs = get_defined_kwargs(epcsim_dir=self.conf['core']['workstation'].get('epcsim_dir', None))
                core = EpcSim(
                    egate=Egate(device_name='EPCSIM', autoconnect=False, get_device=self.create_at_startup,
                                disable_statusbar=self.create_at_startup),
                    workstation=EPCWorkstation(device_name='EPCSIM_WS', autoconnect=self.create_at_startup, **kwargs)
                )

        return core

    def get_btss(self):
        btss = []
        for bts_id, bts_config in enumerate(self.conf['btss']):
            bts = self._get_bts(bts_config, bts_id)
            btss.append(bts)

        return btss

    def _get_bts(self, bts_config, bts_id):
        constructor_params = self._get_bts_constructor_params(bts_config, bts_id)

        if bts_config['type'] == 'AirScaleEnb':
            return AirScaleEnb(**constructor_params)
        elif bts_config['type'] == 'AirScaleGnb':
            return AirScaleGnb(**constructor_params)
        elif bts_config['type'] == 'FzpEnb':
            return FzpEnb(**constructor_params)
        else:
            raise Exception("BTS type: [{}] is not supported".format(bts_config['type']))

    def _get_bts_constructor_params(self, bts_config, bts_id):
        constructor_params = {}
        bts_prefix = 'BTS'

        constructor_params['bts'] = self._get_bts_unix(device_name='{}{}'.format(bts_prefix, bts_id),
                                                       bts_type=bts_config['type'])

        constructor_params['api'] = self._get_api(device_name='{}{}'.format(bts_prefix, bts_id),
                                                  bh_ip=bts_config['bh_ip'])

        if bts_config.get('workstation'):
            constructor_params['workstation'] = self._get_bts_ws(device_name='{}{}_WS'.format(bts_prefix, bts_id))

        if bts_config.get('ems'):
            constructor_params['ems'] = self._get_ems(device_name='EMSSIM{}'.format(bts_id))

        if bts_config.get('syslog'):
            constructor_params['syslog'] = self._get_syslog(device_name='{}{}_SYSLOG'.format(bts_prefix, bts_id))

        return constructor_params

    def _get_bts_unix(self, device_name, bts_type):
        bts = None
        if bts_type in ['AirScaleEnb', 'AirScaleGnb']:
            bts = AirScale(
                fct=Fct(device_name=device_name, autoconnect=self.create_at_startup),
                fsps=None,
            )
        elif bts_type in ['FzpEnb']:
            bts = Fzp(
                unix=FzpFunctionality(device_name=device_name, autoconnect=self.create_at_startup)
            )
        return bts

    def _get_bts_ws(self, device_name):
        return UnixFunctionality(device_name=device_name, autoconnect=self.create_at_startup)

    def _get_ems(self, device_name):
        ems = Ems(
            cli=Emssim(device_name=device_name, autoconnect=False, get_device=self.create_at_startup),
            workstation=EmsWorkstation(device_name='{}_WS'.format(device_name), autoconnect=self.create_at_startup)
        )

        return ems

    def _get_api(self, bh_ip, device_name):
        return COAM(ip=bh_ip, device_name=device_name)

    def _get_syslog(self, device_name):
        return Syslog(device_name=device_name, autoconnect=self.create_at_startup),

    @staticmethod
    def get_proxy_pc_params(config):
        proxy_pc_params = {}
        if config.get("proxy_pc", None):
            proxy_pc_params = {
                'proxy_pc_host': config['proxy_pc']['host'],
                'proxy_pc_login': config['proxy_pc']['login'],
                'proxy_pc_password': config['proxy_pc']['password'],
            }
        return proxy_pc_params
